#!/usr/bin/env bun
// ob-plugin-api-connectors-call — appel API unifié sur les comptes connectés.
// Usage: ob-plugin-api-connectors-call <provider> <METHOD> <path> [--data '<json>'] [--header 'K: V'] [--query 'k=v']
// Exemples:
//   ob-plugin-api-connectors-call github GET /repos/owner/repo/issues
//   ob-plugin-api-connectors-call slack POST /api/chat.postMessage --data '{"channel":"C123","text":"Bonjour"}'
//   ob-plugin-api-connectors-call google GET https://youtube.googleapis.com/youtube/v3/search --query q=robot --query part=snippet
import { apiCall, PROVIDERS, loadConfig } from "/usr/local/bin/ob-plugin-api-connectors-core.js";

const argv = process.argv.slice(2);
const usage = () => {
  console.error(`Usage: ob-plugin-api-connectors-call <provider> <METHOD> <path> [--data '<json>'] [--header 'K: V'] [--query 'k=v']
Providers: ${Object.keys(PROVIDERS).join(", ")}`);
};
const [pid, method, pth] = argv;
if (!pid || !method || !pth || argv.some((a) => a === "-h" || a === "--help")) { usage(); process.exit(argv.length && !argv[0].startsWith("-") ? 0 : 2); }

const data = [];
const headers = [];
const query = [];
for (let i = 3; i < argv.length; i++) {
  const a = argv[i];
  if (a === "--data") data.push(argv[++i] ?? "");
  else if (a === "--header") headers.push(argv[++i] ?? "");
  else if (a === "--query") query.push(argv[++i] ?? "");
  else { console.error(`Option inconnue : ${a}`); usage(); process.exit(2); }
}

let parsed = null;
if (data.length) {
  try { parsed = JSON.parse(data.join(" ")); }
  catch { console.error(JSON.stringify({ error: "--data n'est pas du JSON valide." })); process.exit(2); }
}

const cfg = loadConfig();
const r = await apiCall(pid, { method, path: pth, data: parsed, headers, query }, cfg);
console.log(JSON.stringify(r, null, 2));
if (r.needsKey) process.exit(3);

#!/usr/bin/env bun
// ob-plugin-api-connectors-status — état des connexions (sans jamais révéler les clés).
import { statusSummary, PROVIDERS } from "/usr/local/bin/ob-plugin-api-connectors-core.js";
const rows = statusSummary();
console.log(JSON.stringify({
  providers: rows,
  hint: "Configure ou remplace une clé sur la page Connexions (Dashboards → Connexions). Appels : ob-plugin-api-connectors-call <provider> <METHOD> <path>.",
}, null, 2));
